import type { Request, Response } from 'express';

export interface Product {
  id: string;
  name: string;
  category: 'pottery' | 'textiles' | 'woodwork' | 'jewelry';
  price: number;
  image: string;
  description: string;
  featured: boolean;
}

const products: Product[] = [
  // Pottery
  {
    id: 'p1',
    name: 'Stoneware Serving Bowl',
    category: 'pottery',
    price: 68,
    image: '/airo-assets/images/products/pottery-bowl',
    description: 'A hand-thrown stoneware bowl with a natural ash glaze. Each piece is unique, fired in a wood kiln for a one-of-a-kind finish.',
    featured: true,
  },
  {
    id: 'p2',
    name: 'Artisan Coffee Mug',
    category: 'pottery',
    price: 38,
    image: '/airo-assets/images/products/pottery-mug',
    description: 'Wheel-thrown ceramic mug with a comfortable handle and earthy glaze. Holds 12oz and is dishwasher safe.',
    featured: false,
  },
  {
    id: 'p3',
    name: 'Sculptural Bud Vase',
    category: 'pottery',
    price: 52,
    image: '/airo-assets/images/products/pottery-vase',
    description: 'A delicate hand-built vase with organic form and matte terracotta glaze. Perfect for a single stem or small bouquet.',
    featured: true,
  },
  // Textiles
  {
    id: 't1',
    name: 'Loom-Woven Throw Blanket',
    category: 'textiles',
    price: 145,
    image: '/airo-assets/images/products/textiles-throw',
    description: 'Handwoven on a floor loom using 100% natural wool. Warm, durable, and beautifully textured with a classic stripe pattern.',
    featured: true,
  },
  {
    id: 't2',
    name: 'Market Basket',
    category: 'textiles',
    price: 72,
    image: '/airo-assets/images/products/textiles-basket',
    description: 'Hand-coiled basket made from sustainably harvested seagrass. Sturdy enough for daily use, beautiful enough to display.',
    featured: false,
  },
  {
    id: 't3',
    name: 'Woven Linen Cushion',
    category: 'textiles',
    price: 88,
    image: '/airo-assets/images/products/textiles-cushion',
    description: 'Hand-loomed linen cushion cover with a subtle herringbone weave. Insert included. Removable cover for easy washing.',
    featured: false,
  },
  // Woodwork
  {
    id: 'w1',
    name: 'Turned Walnut Bowl',
    category: 'woodwork',
    price: 120,
    image: '/airo-assets/images/products/woodwork-bowl',
    description: 'Lathe-turned from a single piece of black walnut. The natural grain and live edge make every bowl a unique work of art.',
    featured: true,
  },
  {
    id: 'w2',
    name: 'Floating Wall Shelf',
    category: 'woodwork',
    price: 95,
    image: '/airo-assets/images/products/woodwork-shelf',
    description: 'Hand-crafted floating shelf in white oak with a natural oil finish. Includes hidden mounting hardware. 24" wide.',
    featured: false,
  },
  {
    id: 'w3',
    name: 'End-Grain Cutting Board',
    category: 'woodwork',
    price: 78,
    image: '/airo-assets/images/products/woodwork-cutting-board',
    description: 'End-grain maple and walnut cutting board, finished with food-safe mineral oil. Self-healing surface that protects knife edges.',
    featured: false,
  },
  // Jewelry
  {
    id: 'j1',
    name: 'Sterling Silver Ring',
    category: 'jewelry',
    price: 58,
    image: '/airo-assets/images/products/jewelry-ring',
    description: 'Hand-forged sterling silver ring with a hammered texture. Available in sizes 5–10. Each ring is made to order.',
    featured: false,
  },
  {
    id: 'j2',
    name: 'Stone Pendant Necklace',
    category: 'jewelry',
    price: 84,
    image: '/airo-assets/images/products/jewelry-necklace',
    description: 'Labradorite pendant set in hand-formed sterling silver on an 18" chain. The stone shifts color in different light.',
    featured: false,
  },
  {
    id: 'j3',
    name: 'Opal Drop Earrings',
    category: 'jewelry',
    price: 66,
    image: '/airo-assets/images/products/jewelry-earrings',
    description: 'Delicate drop earrings featuring natural pink opal stones in a simple silver setting. Lightweight and elegant.',
    featured: false,
  },
];

export default function handler(req: Request, res: Response) {
  const { featured, category } = req.query;

  let result = [...products];

  if (featured === 'true') {
    result = result.filter((p) => p.featured);
  }

  if (category && typeof category === 'string') {
    result = result.filter((p) => p.category === category);
  }

  res.json(result);
}

