import { Link, useLoaderData } from 'react-router-dom';
import { motion } from 'motion/react';
import { useState } from 'react';
import { Helmet } from '@dr.pogodin/react-helmet';
import type { Product } from '../server/api/products/GET';

export async function loader() {
  const res = await fetch('/api/products?featured=true');
  if (!res.ok) throw new Response(null, { status: res.status });
  const featured: Product[] = await res.json();
  return { featured };
}

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: (i: number) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, delay: i * 0.12, ease: 'easeOut' as const },
  }),
};

export default function HomePage() {
  const { featured } = useLoaderData() as { featured: Product[] };
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  const handleSubscribe = (e: React.FormEvent) => {
    e.preventDefault();
    if (email) setSubscribed(true);
  };

  return (
    <>
      <Helmet>
        <title>Artisan Goods Co. — Handcrafted with Care, Made to Last</title>
        <meta
          name="description"
          content="Discover handmade pottery, textiles, woodwork, and jewelry crafted by independent artisans. Shop unique pieces made with care."
        />
      </Helmet>

      {/* ── Hero ── */}
      <section className="relative min-h-[90vh] flex items-center overflow-hidden">
        <div
          className="absolute inset-0 bg-cover bg-center"
          style={{ backgroundImage: `url('/airo-assets/images/pages/home/hero')` }}
        />
        {/* Warm overlay */}
        <div className="absolute inset-0 bg-gradient-to-r from-[#2C1A0E]/85 via-[#3D2510]/60 to-[#C4622D]/20" />

        <div className="relative container mx-auto px-6 lg:px-8 py-24">
          <div className="max-w-2xl">
            <motion.p
              custom={0}
              initial="hidden"
              animate="visible"
              variants={fadeUp}
              className="text-sm font-medium tracking-widest uppercase text-[#E8C9A0] mb-6"
            >
              Handmade with intention
            </motion.p>
            <motion.h1
              custom={1}
              initial="hidden"
              animate="visible"
              variants={fadeUp}
              className="font-heading text-5xl md:text-6xl lg:text-7xl font-bold text-white leading-[1.05] mb-6"
            >
              Handcrafted with Care,{' '}
              <span className="text-[#E8A87C]">Made to Last</span>
            </motion.h1>
            <motion.p
              custom={2}
              initial="hidden"
              animate="visible"
              variants={fadeUp}
              className="text-lg text-[#D4C4B0] leading-relaxed mb-10 max-w-lg"
            >
              We connect you with independent makers creating beautiful, functional objects
              for everyday life — pottery, textiles, woodwork, and jewelry.
            </motion.p>
            <motion.div
              custom={3}
              initial="hidden"
              animate="visible"
              variants={fadeUp}
              className="flex flex-wrap gap-4"
            >
              <Link
                to="/products"
                className="inline-flex items-center px-8 py-4 bg-primary text-primary-foreground font-medium rounded-full hover:bg-primary/90 transition-colors duration-200 text-sm tracking-wide"
              >
                Shop Now
              </Link>
              <Link
                to="/about"
                className="inline-flex items-center px-8 py-4 border border-white/40 text-white font-medium rounded-full hover:bg-white/10 transition-colors duration-200 text-sm tracking-wide"
              >
                Our Story
              </Link>
            </motion.div>
          </div>
        </div>
      </section>

      {/* ── Featured Products — Bento Layout ── */}
      <section className="py-24 bg-background">
        <div className="container mx-auto px-6 lg:px-8">
          <div className="flex items-end justify-between mb-12">
            <div>
              <p className="text-xs font-semibold tracking-widest uppercase text-primary mb-3">
                Handpicked
              </p>
              <h2 className="font-heading text-4xl md:text-5xl font-bold text-foreground">
                Featured Pieces
              </h2>
            </div>
            <Link
              to="/products"
              className="hidden md:inline-flex text-sm font-medium text-foreground/60 hover:text-foreground border-b border-foreground/20 hover:border-foreground pb-0.5 transition-colors"
            >
              View all →
            </Link>
          </div>

          {featured.length > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 auto-rows-[340px]">
              {/* Large card — spans 2 rows */}
              {featured[0] && (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, ease: 'easeOut' as const }}
                  whileHover={{ y: -4 }}
                  className="lg:row-span-2 group relative rounded-2xl overflow-hidden cursor-pointer"
                  style={{ height: 'auto' }}
                >
                  <FeaturedCard product={featured[0]} large />
                </motion.div>
              )}

              {/* Two smaller cards stacked */}
              {featured[1] && (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: 0.1, ease: 'easeOut' as const }}
                  whileHover={{ y: -4 }}
                  className="group relative rounded-2xl overflow-hidden cursor-pointer"
                >
                  <FeaturedCard product={featured[1]} />
                </motion.div>
              )}
              {featured[2] && (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: 0.2, ease: 'easeOut' as const }}
                  whileHover={{ y: -4 }}
                  className="group relative rounded-2xl overflow-hidden cursor-pointer"
                >
                  <FeaturedCard product={featured[2]} />
                </motion.div>
              )}

              {/* Wide card — spans 2 columns */}
              {featured[3] && (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: 0.3, ease: 'easeOut' as const }}
                  whileHover={{ y: -4 }}
                  className="lg:col-span-2 group relative rounded-2xl overflow-hidden cursor-pointer"
                >
                  <FeaturedCard product={featured[3]} wide />
                </motion.div>
              )}
            </div>
          )}

          <div className="mt-8 text-center md:hidden">
            <Link
              to="/products"
              className="inline-flex items-center text-sm font-medium text-foreground/60 hover:text-foreground border-b border-foreground/20 hover:border-foreground pb-0.5 transition-colors"
            >
              View all products →
            </Link>
          </div>
        </div>
      </section>

      {/* ── Newsletter ── */}
      <section id="newsletter" className="bg-primary py-20">
        <div className="container mx-auto px-6 lg:px-8">
          <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-10">
            <div className="max-w-md">
              <p className="text-xs font-semibold tracking-widest uppercase text-primary-foreground/60 mb-3">
                Community
              </p>
              <h2 className="font-heading text-4xl md:text-5xl font-bold text-primary-foreground leading-tight">
                Join Our Community
              </h2>
              <p className="mt-4 text-primary-foreground/75 leading-relaxed">
                New makers, seasonal collections, and stories from the studio — delivered to your inbox, never more than twice a month.
              </p>
            </div>

            <div className="w-full lg:w-auto lg:min-w-[420px]">
              {subscribed ? (
                <motion.div
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="bg-primary-foreground/10 border border-primary-foreground/20 rounded-2xl p-8 text-center"
                >
                  <p className="font-heading text-2xl font-bold text-primary-foreground mb-2">
                    Welcome to the community!
                  </p>
                  <p className="text-primary-foreground/70 text-sm">
                    You're on the list. Watch your inbox for something beautiful.
                  </p>
                </motion.div>
              ) : (
                <form onSubmit={handleSubscribe} className="flex flex-col sm:flex-row gap-3">
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="Your email address"
                    required
                    className="flex-1 px-5 py-4 rounded-full bg-primary-foreground/10 border border-primary-foreground/20 text-primary-foreground placeholder:text-primary-foreground/50 focus:outline-none focus:border-primary-foreground/60 text-sm"
                  />
                  <button
                    type="submit"
                    className="px-7 py-4 bg-primary-foreground text-primary font-semibold rounded-full hover:bg-primary-foreground/90 transition-colors text-sm whitespace-nowrap"
                  >
                    Subscribe
                  </button>
                </form>
              )}
              <p className="mt-3 text-xs text-primary-foreground/50 pl-2">
                No spam, ever. Unsubscribe anytime.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* ── Craft Values Strip ── */}
      <section className="py-16 bg-muted/50 border-y border-border/40">
        <div className="container mx-auto px-6 lg:px-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-10 text-center">
            {[
              { title: 'Made by Hand', body: 'Every piece is crafted by an independent maker — no factories, no shortcuts.' },
              { title: 'Built to Last', body: 'We believe in objects that age beautifully and earn a place in your home for years.' },
              { title: 'Maker-First', body: 'Artisans keep the majority of every sale. We exist to support their craft.' },
            ].map((val) => (
              <motion.div
                key={val.title}
                initial={{ opacity: 0, y: 16 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.4, ease: 'easeOut' as const }}
              >
                <h3 className="font-heading text-xl font-bold text-foreground mb-3">{val.title}</h3>
                <p className="text-sm text-muted-foreground leading-relaxed">{val.body}</p>
