/**
 * Products Service
 *
 * Centralised module for all product-related API calls.
 * Pages and loaders should import from here rather than
 * calling fetch('/api/products') directly.
 */

export type ProductCategory = 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

export interface Product {
  id: string;
  name: string;
  category: ProductCategory;
  price: number;
  image: string;
  description: string;
  featured: boolean;
}

export interface GetProductsOptions {
  featured?: boolean;
  category?: ProductCategory;
}

export async function getProducts(options: GetProductsOptions = {}): Promise<Product[]> {
  const params = new URLSearchParams();
  if (options.featured !== undefined) params.set('featured', String(options.featured));
  if (options.category) params.set('category', options.category);

  const query = params.toString();
  const url = `/api/products${query ? `?${query}` : ''}`;

  const res = await fetch(url);
  if (!res.ok) throw new Response(null, { status: res.status });
  return res.json() as Promise<Product[]>;
}

export async function getFeaturedProducts(): Promise<Product[]> {
  return getProducts({ featured: true });
}

